// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(uint256 delta) public {
        // delta = how many blocks ahead of the lock we try to settle (0..3 covers the boundary)
        delta = bound(delta, 0, 3);

        address actor = address(0xA11ce);
        // the winning guess for settling at/inside the target block: blockhash of a
        // not-yet-mined block is 0, so answer == keccak256(abi.encodePacked(bytes32(0)))
        bytes32 winningHash = keccak256(abi.encodePacked(bytes32(0)));

        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(winningHash);

        // move forward by the fuzzed number of blocks (lock happened at block.number, target = +1)
        vm.roll(block.number + delta);

        vm.prank(actor);
        bool ok;
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: settle() may never succeed before the block after the target block (delta <= 1)
        assertTrue(!(ok && delta <= 1));
    }
}
